from jsonb_to_recordset($wall_questions$[{"id":"u02_l03_q121","lesson_id":"u02_l03","difficulty":"medium","prompt":"لماذا وجّه النبي ﷺ في بداية الدعوة إلى عدم كتابة الحديث ثم أذن بعد ذلك؟","options":[{"id":"o1","text":"خشية الانشغال عن القرآن ثم زوال سبب الخشية بعد تدوينه"},{"id":"o3","text":"لأن الصحابة امتنعوا عن حفظ الحديث"},{"id":"o4","text":"لأن جميع الأحاديث كانت مدونة قبل الإسلام"},{"id":"o2","text":"لأن السنة ليست مصدرًا للتشريع"}],"correct_id":"o1","explanation":"ذكر المدخل النهي في البداية لئلا ينشغل الصحابة عن القرآن ثم الإذن بالتدوين.","page":61},{"id":"u02_l03_q124","lesson_id":"u02_l03","difficulty":"medium","prompt":"ما الذي اشتملت عليه بعض المصنفات المبكرة إلى جانب الأحاديث النبوية؟","options":[{"id":"o2","text":"التواريخ السياسية وحدها"},{"id":"o1","text":"أقوال الصحابة وفتاوى التابعين"},{"id":"o4","text":"نصوص غير منسوبة لأي مصدر"},{"id":"o3","text":"تجارب علم الكيمياء فقط"}],"correct_id":"o1","explanation":"بيّن النص جمع مصنفات مبكرة لبعض آثار الصحابة والتابعين.","page":62},{"id":"u02_l03_q125","lesson_id":"u02_l03","difficulty":"hard","prompt":"إذا احتاج طالب إلى تتبع كل الأحاديث المروية عن صحابي معين، فأي نوع من المصنفات الذي صنّف حسب أسماء الرواة يناسبه؟","options":[{"id":"o1","text":"كتب المسانيد مثل مسند الإمام أحمد"},{"id":"o2","text":"كتب الفقه المرتبة حسب شروط الوقف"},{"id":"o3","text":"المعاجم الجغرافية للبلدان"},{"id":"o4","text":"كتب التفسير المرتبة حسب السور فقط"}],"correct_id":"o1","explanation":"وضّح الكتاب أن المسانيد تُرتّب الأحاديث بحسب أسماء رواة الحديث من الصحابة، ومن أمثلتها مسند الإمام أحمد.","page":63},{"id":"u02_l03_q133","lesson_id":"u02_l03","difficulty":"medium","prompt":"ما الذي يميز مرحلة القرن الثالث الهجري في تدوين الحديث؟","options":[{"id":"o2","text":"الاقتصار على حفظ الحديث شفهيًا"},{"id":"o4","text":"إلغاء تصنيف الكتب الفقهية"},{"id":"o1","text":"الاهتمام بتمييز الصحيح والضعيف وظهور كتب الجرح والتعديل"},{"id":"o3","text":"توقف جمع الروايات من البلدان"}],"correct_id":"o1","explanation":"ذكر الدرس توسع التصنيف وبيان درجات الحديث ونشوء كتب الجرح والتعديل في القرن الثالث.","page":62},{"id":"u02_l03_q139","lesson_id":"u02_l03","difficulty":"medium","prompt":"من خدمات الموقع الإلكتروني المعني بالسنة أن يبين صحة الحديث؛ أي عمل يكمل ذلك علميًا؟","options":[{"id":"o3","text":"نشر كل خبر بلا مراجعة"},{"id":"o4","text":"حذف بيان الراوي"},{"id":"o2","text":"إخفاء مصادر الأحاديث"},{"id":"o1","text":"عرض الشروح وطرق البحث والتوثيق"}],"correct_id":"o1","explanation":"يذكر الدرس عرض الحديث وشرحه والبحث في درجته ضمن وسائل الخدمة الإلكترونية.","page":64},{"id":"u02_l03_q140","lesson_id":"u02_l03","difficulty":"hard","prompt":"إذا اجتمع علماء من بلدان مختلفة ليتبادلوا الروايات ويتحققوا منها، فأي غايتين من الرحلة العلمية يجمعون؟","options":[{"id":"o4","text":"الابتعاد عن التعلم من الآخرين"},{"id":"o3","text":"إلغاء الإسناد"},{"id":"o2","text":"تبديل نصوص الحديث حسب البلد"},{"id":"o1","text":"حفظ الحديث وضبط صحته ونشره"}],"correct_id":"o1","explanation":"بيّن إثراء الدرس أن الرحلات تهدف للجمع والتثبت والنشر بين البلدان.","page":65},{"id":"u02_l03_q143","lesson_id":"u02_l03","difficulty":"hard","prompt":"ما الإضافة التي مثّلها القرن الثالث الهجري مقارنة بالبدايات المنظمة للتدوين في الثاني؟","options":[{"id":"o3","text":"إيقاف البحث عن الرواة"},{"id":"o2","text":"إلغاء الاهتمام بجمع الحديث"},{"id":"o4","text":"حصر الحديث في صحيفة واحدة"},{"id":"o1","text":"اتساع التصنيف والتمييز بين درجات الأحاديث والعناية بأحوال الرواة"}],"correct_id":"o1","explanation":"بيّن الكتاب نشوء مصنفات واسعة والعناية بالصحيح والضعيف وكتب الجرح والتعديل.","page":62},{"id":"u02_l03_q151","lesson_id":"u02_l03","difficulty":"medium","prompt":"ما الذي ساعد على بدء تدوين السنة بإذن النبي ﷺ بعد العناية الأولى بحفظ القرآن؟","options":[{"id":"o2","text":"انقطاع حاجة الأمة إلى القرآن"},{"id":"o1","text":"استقرار حفظ القرآن وتمييزه بما يمنع الانشغال عنه"},{"id":"o3","text":"انتهاء دور الحديث في التشريع"},{"id":"o4","text":"تحريم تعليم السنة بعد عصر الصحابة"}],"correct_id":"o1","explanation":"ذكر الكتاب الانتقال إلى تدوين السنة بعد استقرار حفظ القرآن الكريم.","page":61},{"id":"u02_l03_q153","lesson_id":"u02_l03","difficulty":"medium","prompt":"ما الذي يجعل الموطأ شاهدًا على طبيعة التصنيف في القرن الثاني الهجري؟","options":[{"id":"o2","text":"اقتصاره على تراجم شعراء الجاهلية"},{"id":"o4","text":"ترتيبه كل حديث وفق عنوان الصحابي فقط"},{"id":"o1","text":"جمعه أحاديث وأقوالًا وآثارًا مرتبة في أبواب فقهية"},{"id":"o3","text":"اختصاصه بخرائط بلاد الشام"}],"correct_id":"o1","explanation":"عرض الكتاب موطأ مالك ضمن تصنيف القرن الثاني بما فيه من أحاديث وآثار.","page":62},{"id":"u02_l03_q154","lesson_id":"u02_l03","difficulty":"hard","prompt":"أي مصدر أنسب لمن يريد أمثلة لأحاديث جمعها مؤلف بحسب موضوع الصلاة لا بحسب أسماء الصحابة؟","options":[{"id":"o4","text":"سجلات تراجم البلدان فقط"},{"id":"o1","text":"كتب الصحاح والسنن المرتبة بالأبواب الفقهية"},{"id":"o2","text":"كتب المسانيد المرتبة بأسماء الصحابة وحدهم"},{"id":"o3","text":"معاجم الأنساب غير الحديثية"}],"correct_id":"o1","explanation":"فصّل الكتاب الفرق بين تصنيف الأبواب الفقهية وتصنيف المسانيد حسب الرواة.","page":63},{"id":"u02_l03_q158","lesson_id":"u02_l03","difficulty":"medium","prompt":"أي خدمة علمية حديثة تسهم في منع تداول رواية غير ثابتة عند الاستشهاد بها؟","options":[{"id":"o2","text":"نشر كل حديث دون إسناد أو توثيق"},{"id":"o4","text":"حذف معلومات العلماء عن الرواية"},{"id":"o3","text":"استبدال السنة بآراء المتابعين"},{"id":"o1","text":"إتاحة البحث في درجة صحة الحديث وشروحه"}],"correct_id":"o1","explanation":"بيّن الكتاب أن المواقع المختصة تقدم البحث في درجة الأحاديث مع عرض الشروح.","page":64},{"id":"u02_l03_q161","lesson_id":"u02_l03","difficulty":"medium","prompt":"لماذا أولى الصحابة السنة النبوية عناية كبيرة إلى جانب القرآن الكريم؟","options":[{"id":"o1","text":"لأنها مصدر للتشريع يبين أحكام الدين ويهدي إلى تطبيقها"},{"id":"o2","text":"لأنها تُغني عن القرآن وتلغيه"},{"id":"o3","text":"لأنها مجرد أخبار لغوية دون توجيه"},{"id":"o4","text":"لأن حفظها يمنع العمل بأحاديث النبي ﷺ"}],"correct_id":"o1","explanation":"يقرر الدرس مكانة السنة مصدرًا للتشريع وضرورة المحافظة عليها.","page":61},{"id":"u02_l03_q168","lesson_id":"u02_l03","difficulty":"medium","prompt":"لماذا تُعد الفهارس ومحركات البحث الحديثية الموثوقة خدمةً للسنة في العصر الحديث؟","options":[{"id":"o4","text":"تحذف الفروق بين درجات الأحاديث"},{"id":"o3","text":"تستغني عن الرجوع إلى أهل العلم"},{"id":"o2","text":"تجعل كل نص متداول حديثًا صحيحًا"},{"id":"o1","text":"تسهّل العثور على النص وبيان تخريجه ومصادره"}],"correct_id":"o1","explanation":"ذكر الدرس الوسائل الحديثة للفهرسة والتخريج ودورها في الوصول إلى المصادر.","page":65},{"id":"u02_l03_q172","lesson_id":"u02_l03","difficulty":"medium","prompt":"لماذا وجّه النبي ﷺ بعض الصحابة في أول الدعوة إلى عدم كتابة الحديث؟","options":[{"id":"o1","text":"خشية انشغالهم عن القرآن أو اختلاط ما يكتبونه به"},{"id":"o3","text":"لأن الصحابة لم يعرفوا العربية"},{"id":"o2","text":"لأن السنة لا تشرح الأحكام الشرعية"},{"id":"o4","text":"لمنع حفظ أقوال النبي شفهيًا"}],"correct_id":"o1","explanation":"علّل التمهيد التوجيه الأول بالحفاظ على العناية بالقرآن وتدوينه.","page":61},{"id":"u02_l03_q174","lesson_id":"u02_l03","difficulty":"medium","prompt":"ما الذي ميّز نشاط العلماء في القرن الثالث الهجري عند تدوين الأحاديث؟","options":[{"id":"o2","text":"التوقف التام عن ترتيب الأحاديث"},{"id":"o3","text":"الاعتماد على أسماء المدن فقط دون الرواة"},{"id":"o4","text":"الامتناع عن تأليف كتب مستقلة في الحديث"},{"id":"o1","text":"زيادة العناية بدرجات الصحة والضعف وظهور مصنفات للجرح والتعديل"}],"correct_id":"o1","explanation":"ذكر الدرس ازدياد فحص الأسانيد والصحة والضعف وتأليف كتب الجرح والتعديل.","page":62},{"id":"u02_l03_q176","lesson_id":"u02_l03","difficulty":"medium","prompt":"إذا أراد طالب الوصول إلى حديث في باب الصلاة ضمن كتاب مصنف فقهيًا، فما طريقة البحث المناسبة؟","options":[{"id":"o1","text":"الانتقال إلى باب الصلاة الجامع للأحاديث المتعلقة به"},{"id":"o3","text":"حصر البحث في أبواب الحج فقط"},{"id":"o4","text":"تجاهل عناوين الأبواب والموضوعات"},{"id":"o2","text":"البحث عن اسم مؤلف الحديث قبل النظر في الموضوع"}],"correct_id":"o1","explanation":"التصنيف بحسب الأبواب الفقهية يجمع الأحاديث ذات الموضوع الواحد ليسهل الرجوع إليها.","page":63},{"id":"u02_l03_q177","lesson_id":"u02_l03","difficulty":"easy","prompt":"ما فائدة تتيحها المواقع الإلكترونية المتخصصة في السنة؟","options":[{"id":"o4","text":"اعتبار المحتوى المنشور صحيحًا تلقائيًا"},{"id":"o1","text":"البحث في درجة صحة الحديث وقراءة شرحه"},{"id":"o3","text":"نشر كل رواية دون مصدر"},{"id":"o2","text":"الاستغناء عن التثبت من النصوص"}],"correct_id":"o1","explanation":"ذكر الدرس عرض الأحاديث وشروحها والبحث في صحتها من خدمات المواقع المتخصصة.","page":64},{"id":"u02_l03_q181","lesson_id":"u02_l03","difficulty":"medium","prompt":"كيف تكامل جمع السنة وتدوينها مع تصنيفها وشرحها عبر جهود العلماء؟","options":[{"id":"o1","text":"حفظ المادة المروية وتيسير الوصول إلى معانيها وأحكامها"},{"id":"o2","text":"إلغاء الحاجة للتحقق من الروايات"},{"id":"o4","text":"منع تداول السنة بين الأجيال"},{"id":"o3","text":"إحلال الآراء الشخصية محل كل حديث"}],"correct_id":"o1","explanation":"عرض الدرس الجمع والتدوين والتصنيف والشرح بوصفها جهودًا متكاملة للحفظ.","page":62},{"id":"u02_l03_q187","lesson_id":"u02_l03","difficulty":"medium","prompt":"ما أثر انتشار الصحابة في البلدان المفتوحة على جهود جمع الأحاديث؟","options":[{"id":"o3","text":"منع انتقال معرفة السنة بين الأقطار"},{"id":"o1","text":"دفع العلماء إلى الرحلة للقاء الرواة وجمع ما تفرق لديهم"},{"id":"o4","text":"إلغاء العناية بصحة الحديث"},{"id":"o2","text":"حصر الحديث في بلد واحد بعد الوفاة"}],"correct_id":"o1","explanation":"أوضح الدرس انتشار الصحابة وحملهم الحديث إلى الأمصار وما ترتب عليه من رحلات.","page":65},{"id":"u02_l04_q106","lesson_id":"u02_l04","difficulty":"medium","prompt":"ما المبدأ المستفاد من سؤال النبي ﷺ الرجال عن صحة ما نسب إليهم قبل نصحهم؟","options":[{"id":"o2","text":"بناء الحكم على الإشاعة وحدها"},{"id":"o4","text":"التسرع في إطلاق الأحكام"},{"id":"o3","text":"إغفال سماع الطرف الآخر"},{"id":"o1","text":"التثبت من القول قبل مؤاخذة صاحبه"}],"correct_id":"o1","explanation":"استنتج الكتاب التثبت من مخاطبة النبي للرجال.","page":69},{"id":"u02_l04_q107","lesson_id":"u02_l04","difficulty":"medium","prompt":"لماذا نبه الحديث إلى خطأ من يحمل نفسه عبادة لا يطيق دوامها؟","options":[{"id":"o1","text":"لأنها قد تؤدي إلى الفتور وترك الواجبات"},{"id":"o4","text":"لأن الواجبات تترك عند كثرة الطاعات"},{"id":"o3","text":"لأن جميع الأعمال التطوعية محرمة"},{"id":"o2","text":"لأن الاستمرار في العمل لا قيمة له"}],"correct_id":"o1","explanation":"عدد الكتاب الفتور والملل وتضييع الواجبات من آثار التشدد.","page":70},{"id":"u02_l04_q114","lesson_id":"u02_l04","difficulty":"medium","prompt":"كيف بيّن النبي ﷺ للرجال الثلاثة أن الاستقامة لا تعني هجر المباح؟","options":[{"id":"o2","text":"أمرهم بترك جميع النوافل"},{"id":"o3","text":"قرر أن زيادة العبادات واجبة على الجميع"},{"id":"o4","text":"طلب منهم حرمان النفس من الراحة دائمًا"},{"id":"o1","text":"ذكر أنه يصوم ويفطر ويصلي ويرقد ويتزوج"}],"correct_id":"o1","explanation":"وازن الحديث بين العبادة وحقوق النفس والحياة المباحة.","page":69},{"id":"u02_l04_q118","lesson_id":"u02_l04","difficulty":"hard","prompt":"من فهم أن زيادة كل عمل تعبدي مهما بلغت أبلغ في الاقتداء بالنبي ﷺ، ما موضع الخلل في فهمه؟","options":[{"id":"o1","text":"تجاهل الهدي النبوي الذي يوازن بين العبادات والقدرة والحقوق"},{"id":"o4","text":"أداء الواجبات مع مراعاة الاستطاعة"},{"id":"o2","text":"الرجوع إلى فعل النبي ﷺ في ضبط التطوع"},{"id":"o3","text":"التحقق من صحة ما نقل عنه"}],"correct_id":"o1","explanation":"صحح النبي ﷺ الغلو بذكر صيامه وإفطاره وصلاته ونومه وزواجه.","page":69},{"id":"u02_l04_q121","lesson_id":"u02_l04","difficulty":"medium","prompt":"أي هدف يجمع بين توجيه الحديث الشريف إلى العبادة المعتدلة وصيانة حقوق الإنسان على نفسه؟","options":[{"id":"o4","text":"المبالغة في الصيام بلا استراحة"},{"id":"o3","text":"إلزام الناس جميعًا ببرنامج تطوع واحد"},{"id":"o2","text":"ترك العبادة عند الشعور بالمشقة اليسيرة"},{"id":"o1","text":"الاستمرار في الطاعة دون إرهاق النفس"}],"correct_id":"o1","explanation":"يدعو الدرس إلى التوازن في العبادة وعدم تحميل النفس ما لا تطيق.","page":67},{"id":"u02_l04_q122","lesson_id":"u02_l04","difficulty":"easy","prompt":"ما العمل الذي صرّح النبي ﷺ بأنه يجمعه مع الفطر في حديث منهج الإسلام في الحياة؟","options":[{"id":"o4","text":"الصلاة طوال الليل دون نوم"},{"id":"o3","text":"ترك الصيام فرضًا ونفلًا"},{"id":"o1","text":"الصيام في بعض الأيام والفطر في أخرى"},{"id":"o2","text":"صيام جميع الأيام دون انقطاع"}],"correct_id":"o1","explanation":"بيّن الحديث «أصوم وأفطر» في سياق التوازن.","page":68},{"id":"u02_l04_q125","lesson_id":"u02_l04","difficulty":"medium","prompt":"ما الموقف الذي يُظهر أثر الاقتداء بالنبي ﷺ في اختيار الأعمال؟","options":[{"id":"o1","text":"الحرص على العبادة التي يستطيع الإنسان المواظبة عليها"},{"id":"o3","text":"الحكم على الناس من كثرة تطوعهم"},{"id":"o4","text":"ترك جميع النوافل لأن النبي كان يصلي الفرض"},{"id":"o2","text":"التزام أقسى عمل ممكن ثم الانقطاع عنه"}],"correct_id":"o1","explanation":"يفهم من الحديث الاستدامة في العبادة ضمن الوسطية.","page":69},{"id":"u02_l04_q127","lesson_id":"u02_l04","difficulty":"medium","prompt":"أي مبدأ يطبَّق حين يتجنب الطالب إرهاق نفسه بنوافل تُضعفه عن الصلاة المفروضة؟","options":[{"id":"o4","text":"إلغاء حق البدن في الراحة"},{"id":"o2","text":"ترك الفرض عند وجود نافلة"},{"id":"o1","text":"تقديم الفرض وحفظ القدرة على دوام العبادة"},{"id":"o3","text":"اعتبار كل مشقة مطلوبة لذاتها"}],"correct_id":"o1","explanation":"شرح الدرس مراعاة الحقوق وعدم الغلو في التطوع.","page":70},{"id":"u02_l04_q128","lesson_id":"u02_l04","difficulty":"hard","prompt":"إذا كان الفرد قادرًا على التطوع لكنه يعلم أنه سينقطع بسبب الإفراط، فما الإرشاد الأقرب إلى الحديث؟","options":[{"id":"o3","text":"ترك الصلاة والصوم جميعًا"},{"id":"o1","text":"الاعتدال واختيار قدر يستطيع المحافظة عليه"},{"id":"o4","text":"قياس الإيمان بمدى التعب فقط"},{"id":"o2","text":"فرض كل النوافل على نفسه"}],"correct_id":"o1","explanation":"يقرر الحديث ومنهج الدرس اتباع الاعتدال الذي يديم الطاعة.","page":70},{"id":"u02_l04_q129","lesson_id":"u02_l04","difficulty":"medium","prompt":"ماذا يدل تقديم النبي ﷺ نفسه نموذجًا للصلاة والنوم والصيام والفطر؟","options":[{"id":"o3","text":"أن حق الجسد يناقض الالتزام الديني"},{"id":"o4","text":"أن الغلو شرط لصحة العمل"},{"id":"o1","text":"أن السنة العملية معيار للتوازن في العبادة"},{"id":"o2","text":"أن القدوة مقصورة على الكلام"}],"correct_id":"o1","explanation":"بيّن الدرس التصحيح بالاقتداء بهديه العملي في العبادات.","page":71},{"id":"u02_l04_q137","lesson_id":"u02_l04","difficulty":"medium","prompt":"لماذا لا يكون التقرب إلى الله مشروعًا بترك الحقوق الأسرية الأساسية بدعوى العبادة؟","options":[{"id":"o4","text":"لأن الاعتدال يعني ترك الصلاة"},{"id":"o3","text":"لأن مسؤوليات الأسرة تحرم التطوع كله"},{"id":"o1","text":"لأن هدي النبي ﷺ يجمع بين العبادة ومسؤوليات الحياة"},{"id":"o2","text":"لأن العبادة لا تشترط النية"}],"correct_id":"o1","explanation":"يفسر الدرس الحديث على أساس التوازن بين واجبات العبد وحياته.","page":69},{"id":"u02_l04_q138","lesson_id":"u02_l04","difficulty":"hard","prompt":"قال طالب: «كل زيادة في مشقة العبادة أفضل ولو خالفت سنة النبي ﷺ»؛ أين الخطأ؟","options":[{"id":"o4","text":"الامتثال لأوامر الله"},{"id":"o2","text":"الاهتمام بتعلم السنة"},{"id":"o1","text":"اعتبار الغلو أفضل من الاقتداء بالهدي النبوي"},{"id":"o3","text":"الحرص على الاعتدال"}],"correct_id":"o1","explanation":"يحذر الدرس من الغلو ويجعل اتباع السنة معيارًا للاستقامة.","page":69},{"id":"u02_l04_q142","lesson_id":"u02_l04","difficulty":"medium","prompt":"ما الخطأ الذي جمع قرارات الرجال الثلاثة في الحديث؟","options":[{"id":"o4","text":"أداء الفرائض في وقتها"},{"id":"o1","text":"اعتقاد أن التقرب إلى الله يقتضي ترك المباحات أو التشدد الدائم"},{"id":"o3","text":"السؤال عن عبادته في بيته"},{"id":"o2","text":"الحرص على معرفة سنة النبي ﷺ"}],"correct_id":"o1","explanation":"قرر بعضهم ترك النوم أو الإفطار أو الزواج على سبيل التشدد، فنهاهم النبي ﷺ.","page":68},{"id":"u02_l04_q145","lesson_id":"u02_l04","difficulty":"medium","prompt":"بماذا استدل النبي ﷺ على ضرورة استمرار العبادة الممكنة بدل المبالغة المؤدية إلى الملل؟","options":[{"id":"o1","text":"العمل الذي يداوم عليه صاحبه ولو قلّ أفضل"},{"id":"o3","text":"ترك الحقوق الاجتماعية شرط لصحة العبادة"},{"id":"o2","text":"الأعمال لا تقبل إلا مع ترك النوم"},{"id":"o4","text":"الصيام الدائم واجب على الجميع"}],"correct_id":"o1","explanation":"أورد الدرس توجيهًا إلى الأعمال التي يطيقها الإنسان ويستطيع المداومة عليها.","page":69},{"id":"u02_l04_q147","lesson_id":"u02_l04","difficulty":"medium","prompt":"ما سبب عدم القياس على النبي ﷺ في حكم الوصال بالصيام الذي ورد في الإثراء؟","options":[{"id":"o3","text":"لأن الوصال لا يرتبط بالصوم"},{"id":"o4","text":"لأن الأمة مكلفة بكل خصوصيات النبي ﷺ"},{"id":"o2","text":"لأنه كان ممنوعًا عليه وحده"},{"id":"o1","text":"لأنه من الأحكام التي اختص بها النبي ﷺ دون غيره"}],"correct_id":"o1","explanation":"ساق الدرس إباحة الوصال للنبي ﷺ مع النهي عنه لغيره من خصائصه.","page":71},{"id":"u02_l04_q152","lesson_id":"u02_l04","difficulty":"medium","prompt":"ما الذي يساعد على فهم قول الرجال الثلاثة إنهم تقالّوا عبادة النبي ﷺ؟","options":[{"id":"o3","text":"أنهم اعتبروا كل صلاة ممنوعة"},{"id":"o1","text":"أنهم رأوا العبادة قليلة قياسًا إلى ما ظنوه لازمًا لهم"},{"id":"o2","text":"أنهم أنكروا وجود عبادة أصلًا"},{"id":"o4","text":"أنهم تحدثوا عن مقدار المال فقط"}],"correct_id":"o1","explanation":"شرح الكتاب تقالّوها بمعنى رأوها قليلة.","page":68},{"id":"u02_l04_q156","lesson_id":"u02_l04","difficulty":"medium","prompt":"لماذا لا يصلح الانقطاع عن النوم والراحة معيارًا وحيدًا للعبادة المثلى؟","options":[{"id":"o2","text":"لأن العبادة لا صلة لها بحياة المسلم"},{"id":"o3","text":"لأن النوم عبادة مفروضة دائمًا بدل الصلاة"},{"id":"o1","text":"لأن اتباع السنة يوازن بين العبادة وحقوق الجسد والواجبات"},{"id":"o4","text":"لأن أعمال التطوع جميعها ممنوعة"}],"correct_id":"o1","explanation":"شرح الكتاب مراعاة طاقة الإنسان وأن التكليف لا يمنع حقوقه المباحة.","page":69},{"id":"u02_l04_q157","lesson_id":"u02_l04","difficulty":"hard","prompt":"عندما يرفض شخص الزواج باعتباره نقصًا في التديّن رغم قدرته، فأي جانب من سنة النبي ﷺ أهمله؟","options":[{"id":"o2","text":"تحريم الزواج على جميع المتعبدين"},{"id":"o1","text":"إقرار الزواج المباح ضمن منهج الاعتدال"},{"id":"o3","text":"ترك الصلوات من أجل الأسرة"},{"id":"o4","text":"أن الامتناع عن الزواج شرط لصحة الصيام"}],"correct_id":"o1","explanation":"بيّن الحديث أن النبي ﷺ يتزوج وأن الإعراض عن سنته بسبب التشدد غير مقبول.","page":70},{"id":"u02_l04_q158","lesson_id":"u02_l04","difficulty":"medium","prompt":"ما وجه الاستفادة من دوام العبادة المعتدلة مقارنة بالمبالغة التي تفضي إلى الانقطاع؟","options":[{"id":"o1","text":"العمل الممكن المستمر أنفع من التشدد الذي يوقع في الملل"},{"id":"o4","text":"الاستمرار في الطاعة لا قيمة له"},{"id":"o3","text":"العبادة الصحيحة تتوقف على الشهرة"},{"id":"o2","text":"كل عمل ديني يجب أن يتجاوز الطاقة"}],"correct_id":"o1","explanation":"عالج الدرس خطر المبالغة والتنطع ودعا إلى منهج معتدل يستطيع الإنسان الاستمرار فيه.","page":71},{"id":"u02_l04_q165","lesson_id":"u02_l04","difficulty":"hard","prompt":"إذا دافع شخص عن تشدد متواصل بحجة أن العبادة الكثيرة أفضل دائمًا؛ ما الرد الذي يقدمه الشرح؟","options":[{"id":"o3","text":"أن تضييع الواجبات شرط لزيادة الحسنات"},{"id":"o2","text":"تقديم الجهد الجسدي على صحة العمل في كل حالة"},{"id":"o4","text":"أن ترك السنة طريق لتكميل العبادة"},{"id":"o1","text":"العبادة المشروعة تقوم على الاتباع والدوام دون إرهاق يفضي إلى التقصير"}],"correct_id":"o1","explanation":"أوضح شرح الحديث أن المبالغة غير المنضبطة ليست مقياس صلاح العبادة.","page":69},{"id":"u02_l04_q166","lesson_id":"u02_l04","difficulty":"medium","prompt":"ما الصلة بين الزواج والعبادة في تصحيح النبي ﷺ لأقوال الرجال الثلاثة؟","options":[{"id":"o3","text":"الزواج لا يحقق أي مصلحة أسرية"},{"id":"o4","text":"الزواج واجب على كل فرد مهما اختلفت أحواله"},{"id":"o1","text":"الزواج من سنته ولا يتعارض مع الاستقامة"},{"id":"o2","text":"الزواج ممنوع لمن يريد العبادة"}],"correct_id":"o1","explanation":"جعل النبي ﷺ الزواج جزءًا من سنته في مقابلة من أراد تركه للتشدد.","page":69},{"id":"u02_l04_q168","lesson_id":"u02_l04","difficulty":"medium","prompt":"ما الذي يميّز الاعتدال في حديث الرجال الثلاثة عن ترك العبادة؟","options":[{"id":"o2","text":"أنه يبيح تضييع الفرائض"},{"id":"o3","text":"أنه يمنع صلاة التطوع كلها"},{"id":"o1","text":"أنه يجمع الالتزام بالطاعات مع مراعاة حق الإنسان وحاجاته"},{"id":"o4","text":"أنه يلغي الصيام في شهر رمضان"}],"correct_id":"o1","explanation":"بيّن الدرس أن الاعتدال ممارسة العبادة دون إفراط أو تفريط.","page":71},{"id":"u02_l04_q174","lesson_id":"u02_l04","difficulty":"medium","prompt":"لماذا سأل النبي ﷺ الرجال الثلاثة: أنتم الذين قلتم كذا وكذا؟","options":[{"id":"o2","text":"ليأمرهم بزيادة العبادات المرهقة"},{"id":"o1","text":"ليتثبت من قولهم قبل العتاب والتوجيه"},{"id":"o4","text":"ليتجاهل مضمون كلامهم نهائيًا"},{"id":"o3","text":"ليمنعهم من سؤال أهل بيته"}],"correct_id":"o1","explanation":"استنتج الدرس من السؤال ضرورة التثبت قبل توجيه العتاب.","page":69},{"id":"u02_l04_q177","lesson_id":"u02_l04","difficulty":"easy","prompt":"أي حق يمكن أن يتضرر من المبالغة في التعبد على حساب واجبات الحياة؟","options":[{"id":"o4","text":"حق الآخرين في إلزامه بالسهر الدائم"},{"id":"o2","text":"حق الشريعة في منع الاعتدال"},{"id":"o1","text":"حقوق الزوجة والأبناء والعناية بهم"},{"id":"o3","text":"حق الإنسان في إلغاء كل واجب"}],"correct_id":"o1","explanation":"ذكر الدرس حقوق الأسرة من الحقوق التي قد يخل بها التشدد في العبادة.","page":70},{"id":"u02_l04_q181","lesson_id":"u02_l04","difficulty":"medium","prompt":"ما الدافع الذي جعل ثلاثة من الصحابة يسألون أزواج النبي ﷺ عن عبادته؟","options":[{"id":"o3","text":"البحث عن أخبار الحروب وحدها"},{"id":"o2","text":"التأكد من ثروته المالية"},{"id":"o1","text":"الرغبة في التعرف إلى هديه في العبادة والاقتداء به"},{"id":"o4","text":"الحصول على إذن بترك الفرائض"}],"correct_id":"o1","explanation":"يذكر متن الحديث أن ثلاثة نفر جاءوا يسألون عن عبادة النبي ﷺ.","page":68},{"id":"u02_l04_q183","lesson_id":"u02_l04","difficulty":"medium","prompt":"ما الموقف الصحيح ممن يظن أن العبادة تقتضي ترك النوم دائمًا؟","options":[{"id":"o4","text":"يلزم الآخرين بأسلوب تشدد من عنده"},{"id":"o3","text":"يترك الصلاة كلها لكي يستريح"},{"id":"o2","text":"يمتنع عن النوم مطلقًا طلبًا للفضل"},{"id":"o1","text":"يجمع بين قيام الليل وحق الجسد في الراحة"}],"correct_id":"o1","explanation":"بيّن النبي ﷺ أنه يصلي وينام وأن هذا من سنته المعتدلة.","page":69},{"id":"u02_l04_q188","lesson_id":"u02_l04","difficulty":"medium","prompt":"أي نتيجة تربوية يحققها تتبع الصحابة لسيرة النبي ﷺ في شؤونه الخاصة؟","options":[{"id":"o2","text":"حصر العلم في معرفة نسب الرواة"},{"id":"o4","text":"إهمال السؤال عند الحاجة للفهم"},{"id":"o3","text":"اعتبار كل سلوك فردي حكمًا واجبًا"},{"id":"o1","text":"التعلم من التطبيق العملي لا من الأقوال المجردة فقط"}],"correct_id":"o1","explanation":"سجل الدرس سؤال الصحابة عن عبادته ﷺ وحرصهم على اتباع هديه.","page":71},{"id":"u02_l05_q092","lesson_id":"u02_l05","difficulty":"medium","prompt":"أي استجابة صدرت من المنذر بن ساوى بعد وصول رسالة النبي ﷺ؟","options":[{"id":"o4","text":"أعلن حربًا فورًا"},{"id":"o2","text":"أحرق الرسالة"},{"id":"o1","text":"أعلن إسلامه وأخبر النبي ﷺ بذلك"},{"id":"o3","text":"طلب إعفاءه من قراءة الرسالة"}],"correct_id":"o1","explanation":"ورد قبول ملك البحرين الدعوة وكتابته للنبي ﷺ بإسلامه.","page":74},{"id":"u02_l05_q093","lesson_id":"u02_l05","difficulty":"medium","prompt":"إلى من أُرسلت الرسالة التي حملها عمرو بن العاص رضي الله عنه؟","options":[{"id":"o4","text":"إلى النجاشي في الحبشة"},{"id":"o2","text":"إلى هرقل في الروم"},{"id":"o1","text":"إلى جَيفر وعبد ابني الجلندى في عُمان"},{"id":"o3","text":"إلى المقوقس في مصر"}],"correct_id":"o1","explanation":"ذكر الكتاب مَلِكي عُمان جَيفر وعبدًا.","page":74},{"id":"u02_l05_q094","lesson_id":"u02_l05","difficulty":"hard","prompt":"أي غاية تدل عليها دعوة النبي ﷺ الملوك إلى الإسلام مع إبقائهم على حكمهم عند إسلامهم؟","options":[{"id":"o2","text":"تغيير الملوك دون دعوة"},{"id":"o3","text":"التركيز على جمع الأموال"},{"id":"o1","text":"الدعوة إلى الدين لا الاستيلاء على المناصب"},{"id":"o4","text":"إلغاء علاقة الدعوة بالإيمان"}],"correct_id":"o1","explanation":"يوضح الدرس أن مقصد الرسائل لم يكن الاستيلاء على مناصب الملوك.","page":75},{"id":"u02_l05_q105","lesson_id":"u02_l05","difficulty":"medium","prompt":"لماذا عرض النبي ﷺ على بعض زعماء الجزيرة الإبقاء على ملكهم إذا أسلموا؟","options":[{"id":"o3","text":"ليرفض الإسلام عن شعوبهم"},{"id":"o2","text":"ليجعل المنصب هو مضمون الدعوة كله"},{"id":"o4","text":"ليتنازل عن عالمية الرسالة"},{"id":"o1","text":"لتيسير قبول الدعوة دون قصد الاستيلاء على المناصب"}],"correct_id":"o1","explanation":"وضح الكتاب المقصد الدعوي لهذا العرض.","page":74},{"id":"u02_l05_q116","lesson_id":"u02_l05","difficulty":"medium","prompt":"أي سمة في اختيار سفراء الرسائل تبرز مراعاة ثقافات المخاطبين؟","options":[{"id":"o1","text":"معرفة السفير بلغة القوم وعاداتهم"},{"id":"o2","text":"اختيار السفراء دون خبرة بالبلاد"},{"id":"o4","text":"استخدام خطاب واحد دون مراعاة البيئة"},{"id":"o3","text":"منع السفير من التعرف إلى المخاطب"}],"correct_id":"o1","explanation":"أكدت نتائج الرسائل الدراية بلغة القوم وطباعهم.","page":76},{"id":"u02_l05_q117","lesson_id":"u02_l05","difficulty":"medium","prompt":"ما الذي جعل صلح الحديبية نقطة تحول في نشر الدعوة؟","options":[{"id":"o3","text":"قصر الدعوة على مكة بعد الصلح"},{"id":"o1","text":"تفرغ النبي ﷺ لمكاتبة الناس داخل الجزيرة وخارجها"},{"id":"o4","text":"توقف تبليغ الإسلام إلى الزعماء"},{"id":"o2","text":"إيقاف التواصل مع الأمم كلها"}],"correct_id":"o1","explanation":"صرحت المقدمة بأن النبي ﷺ تفرغ بعد الصلح للتواصل مع الملوك والزعماء.","page":73},{"id":"u02_l05_q122","lesson_id":"u02_l05","difficulty":"medium","prompt":"في أي مرحلة من مسيرة الدعوة اشتد إرسال الرسائل إلى الحكام؟","options":[{"id":"o4","text":"قبل الهجرة الأولى إلى الحبشة"},{"id":"o1","text":"بعد صلح الحديبية وانفساح مجال الدعوة"},{"id":"o3","text":"بعد وفاة النبي ﷺ"},{"id":"o2","text":"قبل بدء الوحي"}],"correct_id":"o1","explanation":"يضع الدرس المكاتبات في سياق اتساع الدعوة بعد صلح الحديبية.","page":73},{"id":"u02_l05_q124","lesson_id":"u02_l05","difficulty":"medium","prompt":"أي أسلوب دعوي يتجلى في ذكر اسم المرسل والمرسل إليه بوضوح في الرسالة؟","options":[{"id":"o4","text":"المبالغة في الألفاظ دون معنى"},{"id":"o3","text":"التشويش في المقصود"},{"id":"o1","text":"الوضوح وحسن تنظيم المخاطبة"},{"id":"o2","text":"إخفاء هوية المخاطَب"}],"correct_id":"o1","explanation":"عرضت نماذج الرسائل صياغة رسمية واضحة للمرسل والمرسل إليه.","page":74},{"id":"u02_l05_q125","lesson_id":"u02_l05","difficulty":"medium","prompt":"ما المبدأ الذي تضمنته الدعوة في رسالة النبي ﷺ إلى الزعماء غير المسلمين؟","options":[{"id":"o1","text":"الدعوة إلى عبادة الله وحده"},{"id":"o3","text":"إلغاء كل قيمة أخلاقية"},{"id":"o4","text":"الأمر باتباع أهواء الجماعات"},{"id":"o2","text":"الدعوة إلى عبادة الملوك"}],"correct_id":"o1","explanation":"تقوم الرسائل على الدعوة إلى التوحيد والدخول في الإسلام.","page":75},{"id":"u02_l05_q127","lesson_id":"u02_l05","difficulty":"medium","prompt":"أي قاعدة أخلاقية تتفق مع عرض رسائل النبي ﷺ إلى أهل الكتاب؟","options":[{"id":"o2","text":"السخرية من عقائد المخاطبين"},{"id":"o1","text":"دعوتهم بالحجة وبالتي هي أحسن"},{"id":"o4","text":"الاستعلاء اللفظي دون دعوة"},{"id":"o3","text":"إخفاء هدف الرسالة"}],"correct_id":"o1","explanation":"اشتملت الرسائل على مخاطبة محترمة تتضمن دعوة واضحة إلى الإسلام.","page":76},{"id":"u02_l05_q131","lesson_id":"u02_l05","difficulty":"medium","prompt":"ما الدلالة العامة لإرسال النبي ﷺ كتبه إلى حكام خارج الجزيرة العربية؟","options":[{"id":"o4","text":"إلزام الناس بتغيير لغاتهم"},{"id":"o2","text":"قصر الدعوة على قبيلة واحدة"},{"id":"o1","text":"عالمية الدعوة الإسلامية"},{"id":"o3","text":"انتهاء الحاجة إلى الحوار"}],"correct_id":"o1","explanation":"يبين الدرس حرص النبي ﷺ على تبليغ الإسلام للملوك والزعماء خارج الجزيرة.","page":73},{"id":"u02_l05_q135","lesson_id":"u02_l05","difficulty":"hard","prompt":"لماذا اختلفت صياغة كتاب النبي ﷺ إلى كسرى عن صياغة كتبه إلى النجاشي وهرقل والمقوقس؟","options":[{"id":"o1","text":"لاختلاف معتقد كسرى عن أهل الكتاب الذين خوطبوا"},{"id":"o3","text":"لأن الكتب كانت بلا مضمون ديني"},{"id":"o4","text":"لأن الرسل الآخرين كانوا من بلد واحد"},{"id":"o2","text":"لأن كسرى كان يتحدث العربية وحدها"}],"correct_id":"o1","explanation":"فسر الكتاب التشابه بين كتب أهل الكتاب واختلاف كتاب كسرى من جهة العقيدة.","page":76},{"id":"u02_l05_q137","lesson_id":"u02_l05","difficulty":"medium","prompt":"إذا بدأ خطاب دعوي بالبسملة وذُكر منصب الحاكم باحترام، فأي سمة من رسائل النبي ﷺ تظهر؟","options":[{"id":"o4","text":"الانشغال بالمظاهر دون المعاني"},{"id":"o1","text":"تعظيم الله مع مراعاة مكانة المخاطب"},{"id":"o2","text":"إلغاء مضمون الدعوة"},{"id":"o3","text":"التنازل عن أصل الرسالة"}],"correct_id":"o1","explanation":"بين الدرس أن الرسائل بدأت بالبسملة وراعت ألقاب الحكام.","page":76},{"id":"u02_l05_q142","lesson_id":"u02_l05","difficulty":"medium","prompt":"لماذا خاطب النبي ﷺ بعض حكّام الجزيرة العربية بأسمائهم دون الألقاب الملكية؟","options":[{"id":"o1","text":"لأن أكثرهم كانوا عمّالًا لقوى أخرى ولم يكونوا ملوكًا مستقلين"},{"id":"o2","text":"لأن الدعوة لا تشمل من يملك سلطة"},{"id":"o3","text":"لأن خطاب الحكام ممنوع شرعًا"},{"id":"o4","text":"لأن أسماءهم كانت مجهولة تمامًا"}],"correct_id":"o1","explanation":"وضح الدرس أن كثيرًا منهم كانوا تابعين للروم أو الفرس ولا يملكون قرارًا مستقلًا.","page":74},{"id":"u02_l05_q146","lesson_id":"u02_l05","difficulty":"hard","prompt":"بماذا يختلف رد النجاشي على دعوة النبي ﷺ عن رد كسرى فارس بحسب الرواية المدرسية؟","options":[{"id":"o4","text":"امتنع الاثنان عن لقاء المبعوثين"},{"id":"o2","text":"مزق كلاهما الرسالتين"},{"id":"o1","text":"استجاب النجاشي، بينما مزق كسرى الرسالة"},{"id":"o3","text":"أسلم كسرى ورفض النجاشي"}],"correct_id":"o1","explanation":"ذكر الكتاب إسلام النجاشي وتمزيق كسرى كتاب النبي ﷺ.","page":75},{"id":"u02_l05_q147","lesson_id":"u02_l05","difficulty":"medium","prompt":"ما مهارة السفير التي أبرزها اختيار حاطب بن أبي بلتعة إلى المقوقس؟","options":[{"id":"o4","text":"اختياره بمجرد طول الرحلة"},{"id":"o3","text":"تجنبه الحوار تمامًا"},{"id":"o1","text":"قدرته على المحاورة ومعرفته بالنصرانية"},{"id":"o2","text":"جهله بلغة من يلقاه"}],"correct_id":"o1","explanation":"وردت معرفة حاطب بالنصرانية ومهارته في الحوار ضمن خصائص السفراء.","page":76},{"id":"u02_l05_q154","lesson_id":"u02_l05","difficulty":"hard","prompt":"ما الفارق بين مضمون الرسالة إلى النجاشي والرسالة إلى كسرى من حيث مراعاة المعتقد السابق؟","options":[{"id":"o2","text":"جعلت الرسائل جميعها بلا أي اختلاف في الخطاب"},{"id":"o3","text":"خاطبت الرسالة إلى كسرى المسيحيين فقط"},{"id":"o4","text":"لم تتضمن رسالة النجاشي دعوة إلى التوحيد"},{"id":"o1","text":"تضمنت رسالة النجاشي خطابًا ملائمًا لمسيحيته بخلاف كسرى"}],"correct_id":"o1","explanation":"أوضح الدرس مراعاة خلفية ملوك أهل الكتاب في الرسائل.","page":75},{"id":"u02_l05_q156","lesson_id":"u02_l05","difficulty":"medium","prompt":"لماذا استفسر هرقل من أبي سفيان عن النبي ﷺ قبل اتخاذ قراره؟","options":[{"id":"o1","text":"ليتحقق من نسبه وصدقه وأخلاقه وحقيقة دعوته"},{"id":"o4","text":"ليبحث في عدد أبواب كتب السنة"},{"id":"o2","text":"ليتعلم طريقة ترتيب الميراث"},{"id":"o3","text":"ليحدد مدة عدة المتوفى عنها زوجها"}],"correct_id":"o1","explanation":"يروي الدرس سؤال هرقل أبا سفيان عن النبي ﷺ واستقصاء أخباره.","page":76},{"id":"u02_l05_q158","lesson_id":"u02_l05","difficulty":"medium","prompt":"كيف كانت استجابة المقوقس بعد قراءة رسالة النبي ﷺ وفق النص المدرسي؟","options":[{"id":"o2","text":"مزّق الرسالة ثم أعلن إسلامه"},{"id":"o4","text":"رفض لقاء المبعوث والتحدث إليه"},{"id":"o3","text":"أعلن الإسلام فورًا ونقل حكمه إلى المدينة"},{"id":"o1","text":"أكرم المبعوث وأرسل هدية دون أن يسلم"}],"correct_id":"o1","explanation":"ذكر الكتاب تكريم المقوقس لحامل الرسالة وإرسال هدية مع عدم إسلامه.","page":76},{"id":"u02_l05_q161","lesson_id":"u02_l05","difficulty":"medium","prompt":"ما الغاية الأساسية من توجيه النبي ﷺ رسائل إلى حكام خارج الجزيرة العربية؟","options":[{"id":"o1","text":"دعوتهم إلى الإسلام وإبلاغهم عموم الرسالة"},{"id":"o3","text":"تحديد مواعيد الحج لهم"},{"id":"o4","text":"استطلاع أسعار التجارة في بلادهم"},{"id":"o2","text":"جمع الضرائب من جميع الممالك بالقوة"}],"correct_id":"o1","explanation":"ركز الدرس على الدعوة إلى الإسلام عالمية الرسالة عبر المراسلات.","page":73},{"id":"u02_l05_q163","lesson_id":"u02_l05","difficulty":"medium","prompt":"ما الذي يبين أن الرسائل النبوية لم تكن صورة واحدة متماثلة تمامًا؟","options":[{"id":"o1","text":"مراعاة حال المخاطب مع ثبات أصل الدعوة"},{"id":"o2","text":"أنها خلت كلها من الدعوة الدينية"},{"id":"o3","text":"أنها كتبت باللغة العربية فقط إلى كل الحكام"},{"id":"o4","text":"أنها طُبعت في صحيفة واحدة للجميع"}],"correct_id":"o1","explanation":"أبرز الكتاب اختلاف الخطاب بحسب حال المرسل إليه مع وحدة مقصد الإسلام.","page":74}]$wall_questions$::jsonb)
